//! External reference vectors with their expected verdicts (SWREQ-RELAY-BP-P02,
//! P04). Test-only.
//!
//! Every bundle here is transcribed from RFC 9173 (BPSec Default Security
//! Contexts) Appendix A, from the RFC text, with the section cited. None is
//! generated by this crate. RFC 9171 itself publishes no example bundle in hex,
//! so RFC 9173 Appendix A is the RFC-sourced corpus. The A.2.1.3 and A.4.1.3
//! "original bundle" encodings are byte-identical to A.1.1.3 and are not
//! repeated.
//!
//! Expected verdicts:
//!
//! * Structural: all six decode (RFC 9171 4.1 / 4.3 shape, canonical CBOR).
//! * Strict (RFC 9171 4.3.1 primary-CRC rule and 4.4.2 Bundle Age rule): the
//!   plan records RFC 9173 A.1-A.4 as expected-strict-verdict REJECT
//!   (docs/RELEASE-PLAN.md, relay-bp decisions). A.1, A.2 and A.4 are rejected
//!   here. **A.3 is DISPUTED** (errata on RFC 9173 A.3); it is recorded as
//!   disputed and NOT used as a conformance vector. Its BIB lists block 0 as a
//!   target and it carries one Bundle Age block, so this crate's strict rules
//!   observe it as passing; the test below pins that observation so a change
//!   in behaviour is noticed, without claiming it as the conformant verdict.

use crate::{DecodeError, Mode, StrictViolation, decode};
use std::vec::Vec;

/// Hex string to bytes; whitespace is ignored. Test-only helper.
pub(crate) fn hex(s: &str) -> Vec<u8> {
    let digits: Vec<u8> = s.bytes().filter(|b| !b.is_ascii_whitespace()).collect();
    assert!(digits.len() % 2 == 0, "odd hex length");
    digits
        .chunks(2)
        .map(|p| u8::from_str_radix(core::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}

