/// Expected strict-mode verdict of a vector.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Strict {
    /// Rejected with this violation.
    Reject(StrictViolation),
    /// Disputed (errata). The observed verdict is recorded, not claimed.
    Disputed { observed_ok: bool },
}

struct Vector {
    name: &'static str,
    hex: &'static str,
    /// Number of canonical blocks the structural decode must yield.
    blocks: usize,
    strict: Strict,
}

const PRIMARY_CRC_MISSING: Strict = Strict::Reject(StrictViolation::PrimaryCrcMissing);

/// The table. The strict reason is the FIRST strict rule that fails; A.1, A.2
/// and A.4 also lack the Bundle Age block their creation time 0 requires.
const TABLE: [Vector; 6] = [
    Vector {
        name: "RFC 9173 A.1.1.3 original",
        hex: RFC9173_A1_ORIGINAL,
        blocks: 1,
        strict: PRIMARY_CRC_MISSING,
    },
    Vector {
        name: "RFC 9173 A.1.4 final (BIB targets payload only)",
        hex: RFC9173_A1_FINAL,
        blocks: 2,
        strict: PRIMARY_CRC_MISSING,
    },
    Vector {
        name: "RFC 9173 A.2.4 final (BCB, no BIB)",
        hex: RFC9173_A2_FINAL,
        blocks: 2,
        strict: PRIMARY_CRC_MISSING,
    },
    Vector {
        name: "RFC 9173 A.3.1.4 original (Bundle Age, no BIB)",
        hex: RFC9173_A3_ORIGINAL,
        blocks: 2,
        strict: PRIMARY_CRC_MISSING,
    },
    Vector {
        name: "RFC 9173 A.3.5 final (DISPUTED)",
        hex: RFC9173_A3_FINAL,
        blocks: 4,
        strict: Strict::Disputed { observed_ok: true },
    },
    Vector {
        name: "RFC 9173 A.4.5 final (BIB encrypted by BCB)",
        hex: RFC9173_A4_FINAL,
        blocks: 3,
        strict: PRIMARY_CRC_MISSING,
    },
];

#[test]
fn rfc9173_vectors_structural_verdicts() {
    for v in &TABLE {
        let b = hex(v.hex);
        let view = decode(&b, Mode::Structural).unwrap_or_else(|e| panic!("{}: {e:?}", v.name));
        assert_eq!(view.blocks().len(), v.blocks, "{}", v.name);
        assert_eq!(
            view.payload().map(<[u8]>::len),
            Some(35),
            "{}: payload is the 35-byte A.1.1.2 string (or its ciphertext)",
            v.name
        );
    }
}

#[test]
fn rfc9173_vectors_strict_verdicts() {
    for v in &TABLE {
        let b = hex(v.hex);
        let got = decode(&b, Mode::Strict);
        match v.strict {
            Strict::Reject(why) => {
                assert_eq!(got, Err(DecodeError::Strict(why)), "{}", v.name)
            }
            Strict::Disputed { observed_ok } => {
                assert_eq!(got.is_ok(), observed_ok, "{}: observation changed", v.name)
            }
        }
    }
}

#[test]
fn rfc9173_a1_a2_strict_reject() {
    // SWREQ-RELAY-BP-P04 names these two explicitly.
    for h in [RFC9173_A1_FINAL, RFC9173_A2_FINAL] {
        assert_eq!(
            decode(&hex(h), Mode::Strict),
            Err(DecodeError::Strict(StrictViolation::PrimaryCrcMissing))
        );
    }
    // Creation time is 0 in both and neither carries a Bundle Age block, so the
    // 4.4.2 rule fails as well: with the primary CRC rule satisfied by a BIB on
    // block 0, the verdict would still be reject. Checked on A.1 by adding a
    // BIB target 0 to its view.
    let b = hex(RFC9173_A1_FINAL);
    let mut view = decode(&b, Mode::Structural).unwrap();
    let mut with_bib = crate::BundleView::new(view.primary);
    with_bib
        .push(crate::CanonicalBlock {
            block_type: crate::BLOCK_BIB,
            number: 9,
            flags: 0,
            crc_type: crate::CrcType::None,
            data: &[0x81, 0x00],
        })
        .unwrap();
    for blk in view.blocks() {
        with_bib.push(*blk).unwrap();
    }
    view = with_bib;
    let mut out = [0u8; 256];
    assert_eq!(
        crate::encode(&view, &mut out),
        Err(crate::EncodeError::Invalid(DecodeError::Strict(
            StrictViolation::BundleAgeMissing
        )))
    );
}

#[test]
fn rfc9173_a3_recorded_as_disputed() {
    // RFC 9173 A.3 is disputed (errata) and is NOT a conformance vector. This
    // test records only what the decoder does with it: the structural decode
    // succeeds with the four blocks A.3.2 lists (BIB #3 targeting [0, 2], BCB
    // #4, Bundle Age #2 = 300 ms, payload #1).
    let b = hex(RFC9173_A3_FINAL);
    let v = decode(&b, Mode::Structural).unwrap();
    let kinds: Vec<(u64, u64)> = v
        .blocks()
        .iter()
        .map(|b| (b.block_type, b.number))
        .collect();
    assert_eq!(kinds, [(11, 3), (12, 4), (7, 2), (1, 1)]);
    assert!(v.bib_targets_primary());
    assert_eq!(v.bundle_age(), Some(300));
}
